from pathlib import Path
import os, stat, hashlib
for p in (Path('/work/CLAUDE.md'), Path('/work/AGENTS.md')):
    print(f'PATH {p}')
    try:
        s=p.lstat()
        print(' exists_entry=True', 'mode='+oct(stat.S_IMODE(s.st_mode)), 'uid='+str(s.st_uid), 'gid='+str(s.st_gid), 'type='+('symlink' if stat.S_ISLNK(s.st_mode) else 'regular' if stat.S_ISREG(s.st_mode) else 'other'))
        if p.is_symlink(): print(' target='+os.readlink(p))
        if stat.S_ISREG(s.st_mode):
            b=p.read_bytes(); print(' readable=True', 'size='+str(len(b)), 'sha256='+hashlib.sha256(b).hexdigest())
    except FileNotFoundError:
        print(' exists_entry=False')
